// Reads node 1 and builds the Actor input. Edit node 1, not this code.
const s = $input.first().json;
const number = (value, fallback) => { const n = Number(value); return Number.isFinite(n) ? n : fallback; };
const clamp = (value, min, max, fallback) => Math.min(max, Math.max(min, number(value, fallback)));
const queries = [...new Set(String(s.searchQueries ?? '').split(',').map((q) => q.trim()).filter(Boolean))];
if (!queries.length) throw new Error('Add at least one search phrase to "searchQueries" in node 1 (comma-separated).');
if (queries.length > 10) throw new Error(`Use at most 10 search phrases per run; node 1 has ${queries.length}.`);
const uploadDate = ['today', 'week', 'month', 'year'].includes(String(s.uploadDate).trim()) ? String(s.uploadDate).trim() : 'week';
const country = String(s.country ?? 'US').trim().toUpperCase();
return [{
  json: {
    maxCostUsd: clamp(s.maxCostUsd, 0.01, 0.5, 0.1),
    actorInput: {
      queries,
      resultType: 'videos',
      sortBy: 'viewCount',
      uploadDate,
      maxResultsPerQuery: Math.round(clamp(s.maxResultsPerQuery, 4, 50, 10)),
      language: 'en',
      country: /^[A-Z]{2}$/.test(country) ? country : 'US'
    }
  }
}];

// Scores every video against the other videos from the same search.
// velocity = views / days since upload (at least 1 day); breakout ratio = velocity / median velocity of that search.
const settings = $('1. Set your niche searches').first().json;
const queries = $('Build Actor Input from Settings').first().json.actorInput.queries;
const number = (value, fallback) => { const n = Number(value); return Number.isFinite(n) ? n : fallback; };
const minRatio = Math.max(1, number(settings.minBreakoutRatio, 2));
const minViews = Math.max(0, number(settings.minViews, 1000));
const minVideos = Math.max(3, Math.round(number(settings.minVideosPerQuery, 4)));
const maxBreakouts = Math.min(25, Math.max(1, Math.round(number(settings.maxBreakoutsPerRun, 15))));

// Video IDs already in the sheet are never sent again.
const logged = new Set($input.all().map((item) => String(item.json['Video ID'] ?? '').trim()).filter(Boolean));
const rows = $('2. Search YouTube with Apify').all().map((item) => item.json)
  .filter((row) => row && row.resultType === 'video' && row.videoId);

// YouTube shows ages as "3 days ago" or, more often, "3d ago", "15h ago", "11mo ago", "2y ago".
function ageInDays(text) {
  const match = /(\d+)\s*(seconds?|secs?|s|minutes?|mins?|months?|mos?|m|hours?|hrs?|h|days?|d|weeks?|wks?|w|years?|yrs?|y)\s+ago\b/i.exec(String(text ?? ''));
  if (!match) return null;
  const unit = match[2].toLowerCase();
  const days = unit.startsWith('mo') ? 30 : unit.startsWith('m') ? 1 / 1440 : unit.startsWith('s') ? 1 / 86400
    : unit.startsWith('h') ? 1 / 24 : unit.startsWith('d') ? 1 : unit.startsWith('w') ? 7 : 365;
  return Number(match[1]) * days;
}
function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}
const round = (value, digits) => Math.round(value * 10 ** digits) / 10 ** digits;

// Group by the search each row came from; phrases are matched ignoring case and spacing.
const keyOf = (query) => String(query ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
const byQuery = new Map(queries.map((query) => [keyOf(query), { query, videos: [] }]));
let notScored = 0;
for (const row of rows) {
  const age = ageInDays(row.publishedTimeText);
  const views = Number.isFinite(row.viewCount) && row.viewCount >= 0 ? row.viewCount : null;
  if (row.isShort || row.isLive || row.isUpcoming || age === null || views === null) { notScored += 1; continue; }
  const key = keyOf(row.query);
  if (!byQuery.has(key)) byQuery.set(key, { query: String(row.query ?? ''), videos: [] });
  byQuery.get(key).videos.push({ ...row, ageDays: age, viewsPerDay: views / Math.max(age, 1) });
}

const skippedSearches = [];
const candidates = [];
let scoredVideos = 0;
for (const { query, videos } of byQuery.values()) {
  if (videos.length < minVideos) { skippedSearches.push(`${query} (${videos.length} scorable videos, need ${minVideos})`); continue; }
  const typical = median(videos.map((video) => video.viewsPerDay));
  if (!(typical > 0)) { skippedSearches.push(`${query} (typical views per day is 0)`); continue; }
  scoredVideos += videos.length;
  for (const video of videos) {
    const ratio = video.viewsPerDay / typical;
    if (ratio >= minRatio && video.viewCount >= minViews) candidates.push({ ...video, breakoutRatio: ratio });
  }
}

// One row per video: if it broke out in two searches, keep the stronger one.
const strongest = new Map();
for (const video of candidates) {
  const previous = strongest.get(video.videoId);
  if (!previous || video.breakoutRatio > previous.breakoutRatio) strongest.set(video.videoId, video);
}
const ranked = [...strongest.values()].sort((a, b) => b.breakoutRatio - a.breakoutRatio);
const alreadyLogged = ranked.filter((video) => logged.has(video.videoId)).length;
const fresh = ranked.filter((video) => !logged.has(video.videoId));
const breakouts = fresh.slice(0, maxBreakouts).map((video) => ({
  videoId: video.videoId,
  query: video.query,
  rank: video.rank,
  title: video.title ?? '',
  channel: video.channelName ?? '',
  published: video.publishedTimeText,
  daysSinceUpload: round(video.ageDays, 1),
  views: video.viewCount,
  viewsPerDay: Math.round(video.viewsPerDay),
  breakoutRatio: round(video.breakoutRatio, 2),
  durationSeconds: Number.isFinite(video.durationSeconds) ? video.durationSeconds : '',
  url: `https://www.youtube.com/watch?v=${encodeURIComponent(video.videoId)}`
}));

const summary = {
  searches: queries.length,
  videosReturned: rows.length,
  scoredVideos,
  notScored,
  skippedSearches,
  alreadyLogged,
  heldForNextRun: Math.max(0, fresh.length - breakouts.length),
  newBreakouts: breakouts.length
};
let message;
if (breakouts.length) message = `${breakouts.length} new breakout videos found.`;
else if (!rows.length) message = 'The Actor returned no videos for these searches. Nothing was written to Google Sheets or Slack.';
else message = `No new breakout videos this run: ${scoredVideos} videos scored, ${notScored} not scored, ${alreadyLogged} breakouts already in the sheet, ${skippedSearches.length} searches skipped. Nothing was written to Google Sheets or Slack.`;
return [{ json: { hasBreakouts: breakouts.length > 0, message, summary, breakouts } }];

// Checks the OpenAI answer before anything is written. A bad answer stops the run with no writes.
function parseStructured(root) {
  const seen = new Set();
  function visit(value) {
    if (value === null || value === undefined) return null;
    if (typeof value === 'string') {
      const text = value.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\s*\x60\x60\x60$/, '');
      if (!text.startsWith('{')) return null;
      try { return visit(JSON.parse(text)); } catch { return null; }
    }
    if (typeof value !== 'object' || seen.has(value)) return null;
    seen.add(value);
    if (Array.isArray(value.angles)) return value;
    for (const nested of Array.isArray(value) ? value : Object.values(value)) {
      const found = visit(nested);
      if (found) return found;
    }
    return null;
  }
  return visit(root);
}
const scored = $('Score New Breakouts').first().json;
const byId = new Map(scored.breakouts.map((video) => [video.videoId, video]));
const parsed = parseStructured($input.first().json);
const reject = (reason) => [{ json: { valid: false, message: `OpenAI angles were rejected (${reason}). Nothing was written to Google Sheets or Slack; run the workflow again.` } }];
if (!parsed) return reject('no JSON with an "angles" list');
if (parsed.angles.length < 1 || parsed.angles.length > 5) return reject(`${parsed.angles.length} angles, expected 1 to 5`);

const angleOf = new Map();
const angles = [];
for (const entry of parsed.angles) {
  const angle = String(entry?.angle ?? '').trim();
  const whyItWorks = String(entry?.whyItWorks ?? '').trim();
  if (!angle || !whyItWorks || !Array.isArray(entry.videoIds)) return reject('an angle is missing its name, reason or videos');
  const videoIds = [...new Set(entry.videoIds.map(String))].filter((id) => byId.has(id) && !angleOf.has(id));
  for (const id of videoIds) angleOf.set(id, angle.slice(0, 120));
  if (videoIds.length) angles.push({ angle: angle.slice(0, 120), whyItWorks: whyItWorks.slice(0, 400), videoIds });
}
if (!angles.length) return reject('no angle refers to a video from this run');

const observedAt = $now.toUTC().toFormat("yyyy-MM-dd HH:mm 'UTC'");
return scored.breakouts.map((video) => ({
  json: {
    valid: true,
    angles,
    'Observed at': observedAt,
    'Query': video.query,
    'Rank': video.rank,
    'Video title': video.title,
    'Channel': video.channel,
    'Published': video.published,
    'Days since upload': video.daysSinceUpload,
    'Views': video.views,
    'Views per day': video.viewsPerDay,
    'Breakout ratio': video.breakoutRatio,
    'Duration (s)': video.durationSeconds,
    'Angle': angleOf.get(video.videoId) ?? 'Other',
    'Video URL': video.url,
    'Video ID': video.videoId
  }
}));

// Builds one Slack message after the sheet write succeeded.
const rows = $('Check Angles and Build Sheet Rows').all().map((item) => item.json);
const summary = $('Score New Breakouts').first().json.summary;
const byId = new Map(rows.map((row) => [row['Video ID'], row]));
const clean = (text) => String(text ?? '').replace(/[<>|*_~`]/g, ' ').replace(/\s+/g, ' ').trim();
const lines = [
  `*YouTube breakouts: ${rows.length} new videos* (${rows[0]['Observed at']})`,
  'Breakout ratio = views per day divided by the typical (median) views per day of the same search.'
];
const placed = new Set();
const sections = rows[0].angles.map((angle) => ({ ...angle, rows: angle.videoIds.map((id) => byId.get(id)).filter(Boolean) }));
const others = rows.filter((row) => !sections.some((section) => section.videoIds.includes(row['Video ID'])));
if (others.length) sections.push({ angle: 'Other', whyItWorks: 'Not grouped by the AI.', rows: others });
for (const section of sections) {
  lines.push('', `*${clean(section.angle)}*: ${clean(section.whyItWorks)}`);
  for (const row of section.rows) {
    if (placed.has(row['Video ID'])) continue;
    placed.add(row['Video ID']);
    lines.push(`• <${row['Video URL']}|${clean(row['Video title']).slice(0, 90)}> by ${clean(row['Channel'])}: ${Number(row['Views']).toLocaleString('en-US')} views, ${row['Breakout ratio']}x, ${row['Published']}`);
  }
}
const notes = [`${summary.scoredVideos} videos scored across ${summary.searches} searches`];
if (summary.notScored) notes.push(`${summary.notScored} Shorts, live or undated results not scored`);
if (summary.alreadyLogged) notes.push(`${summary.alreadyLogged} breakouts already in your sheet`);
if (summary.heldForNextRun) notes.push(`${summary.heldForNextRun} more held back by maxBreakoutsPerRun`);
lines.push('', `_${notes.join('; ')}._`);
if (summary.skippedSearches.length) lines.push(`_Skipped searches (too few videos for a fair median): ${clean(summary.skippedSearches.join('; '))}._`);
return [{ json: { text: lines.join('\n') } }];
